import Global from "../storage/global.js";
import { main } from "../index.js";
import { filterObjs, filterNames } from "../controller/filter.js";
import { createSelectOptions } from "../helpFunctions.js";
import { todosController } from "../controller/todoController.js";
import "../style/todopage.css";

export default function todosUi() {
    const sortSelect = document.createElement("select");
    sortSelect.setAttribute("id", "sort-select");
    sortSelect.classList.add("sort-select");
    const filterNames = filterObjs.map((item) => item.name);
    createSelectOptions(sortSelect, filterNames, "current", "current-sort");

    const todosDiv = document.createElement("div");
    todosDiv.classList.add("todos-ui-div");
    todosDiv.setAttribute("id", "todos-ui-div");
    main.appendChild(sortSelect);
    main.appendChild(todosDiv);
    renderTodos(Global.allTodos, todosDiv);
    todosController();
}

export function renderTodos(arrTodos, node, filter = filterObjs[1].filter) {
    node.textContent = "";
    console.log(arrTodos);
    arrTodos = filter(arrTodos);
    console.log(arrTodos);
    console.log(filter);
    for (const todo of arrTodos) {
        const title = document.createElement("h1");
        title.classList.add("todo-ui-item-title");
        title.textContent = todo.title;

        const todoItem = document.createElement("button");
        todoItem.classList.add("todo-ui-item");
        todoItem.appendChild(title);

        node.appendChild(todoItem);

    }
}
