import { renderTodos} from "../ui/todosUi.js";
import { main } from "../index.js";
import projectUi from "../ui/projectUi.js";
import { filterObjs } from "./filter.js";
import Global from "../storage/global.js";


export function todosController() {
    const sortSelect = document.querySelector("#sort-select");
    const todosDiv = document.querySelector("#todos-ui-div");
    const todosItem = document.querySelectorAll(".todo-ui-item");


    sortSelect.addEventListener("change", (e) => {
        const selectedOption = e.currentTarget.value;
        const filterMethod = filterObjs.find(obj => obj.name === selectedOption);
        const allTodos = Global.allTodos;
        renderTodos(allTodos, todosDiv, filterMethod.filter);
    });

    for (const item of todosItem) {
        item.addEventListener("click", () => {
            main.textContent = "";
            projectUi();
        });
    }
}
