
function sortByDayRecent (arrTodos) {
    return [...arrTodos].sort((a, b) => {
        return a.dueDate - b.dueDate;
    });
}

function sortByDayLatest (arrTodos) {
    return [...arrTodos].sort((a, b) => {
        return b.dueDate - a.dueDate;
    });
}

function sortByPriorityHigh (arrTodos) {
    return [...arrTodos].sort((a, b) => {
        const aPriority = a.priority === "low" ? 1 : a.priority === "medium" ? 2 : 3;
        const bPriority = b.priority === "low" ? 1 : b.priority === "medium" ? 2 : 3;
        return bPriority - aPriority;
    });
}

function sortByPriorityLow (arrTodos) {
    return [...arrTodos].sort((a,b) => {
        const aPriority = a.priority === "low" ? 1 : a.priority === "medium" ? 2 : 3;
        const bPriority = b.priority === "low" ? 1 : b.priority === "medium" ? 2 : 3;
        return aPriority - bPriority;
    });
}

function sortByLetter (arrTodos) {
    return [...arrTodos].sort((a, b) => {
        return a.title.localeCompare(b.title);
    });
}

class Sort {
    constructor(name, filterMethod) {
        this.name = name;
        this.filter = filterMethod;
    }
}

const sortAZ = new Sort("a-z", sortByLetter);
const sortLatestDate = new Sort("Latest", sortByDayLatest);
const sortRecentDate = new Sort("recent", sortByDayRecent);
const sortLowPriority = new Sort("lowest priority", sortByPriorityLow);
const sortHighPriority = new Sort("highest priority", sortByPriorityHigh);

export const filterObjs = [sortHighPriority, sortLowPriority, sortRecentDate, sortLatestDate, sortAZ];
